query:
Why is it challenging to solve this non ASLR'd exploitation challenge without several iterations of the main while loop?

 // gcc -g -I ../includes -O0 -fno-stack-protector -o 06_level_2 06_level_2.c -ldl

 #include <stdio.h>
 #include <string.h>
 #include "06_level_2.h"
 #include "wargames.h"

 void print_label(const char * text)
 {
  // print top of speech bubble
  printf(" .");
  for(int i = 0; i < strlen(text) + 5; i++)
  printf("-");

  // print edges & some padding
  printf("---.
/");
  for(int i = 0; i < strlen(text) + 9; i++)
  printf(" ");
  printf(" \
");

  // print label text
  printf("{ < %s > }
", text);

  // print edges & some padding
  printf("\"); 
  for(int i = 0; i < strlen(text) + 9; i++)
  printf(" ");
  printf(" /
");

  // print the bottom of the label
  printf(" #");
  for(int i = 0; i < strlen(text) + 5; i++)
  printf("-");
  printf("---#
");
 }

 unsigned int g_menu_choice;
 void main()
 {
  init_wargame();

  printf("------------------------------------------------------------
");
  printf("--[ DEP & ROP Level #2 - LabelMaker Pro 
");
  printf("------------------------------------------------------------
");

  // buffer to hold user input & label text
  char text[128] = {};
  char buffer[128] = {};

  while(1) {
  printf("1. Create a Label
");
  printf("2. Quit
");

  g_menu_choice = get_number();

  if (g_menu_choice == 1) {

  printf("Enter Label Text: ");

  fgets(buffer, sizeof(buffer), stdin);
  buffer[strcspn(buffer, "
")] = 0;

  // Build out the final label text...
  strcat(text, "[LabelMaker Pro] ");
  strcat(text, buffer);

  // print out the label
  print_label(text);

  // clean up the label buffer
  memset(text, 0, 128);
  }

  if (g_menu_choice == 2) {
  break;
  }
  }
 }

Options:
A) The only way to write null bytes that may exist in the payload (such as a code addresses) is to abuse the null terminator placed by the string functions.
B) The program explicitly limits how much stack data can be read in at once, requiring several iterations to read a big ROP chain into memory.
C) The level requires users to bypass stack cookies which requires them to first leak the cookie, then overwrite it using strcat.
D) None of the above.

Answer with the letter of the correct option and nothing else.

